use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside this
/// set would trap at the boundary, so a subscription naming any other host is
/// recorded as a failure instead of being attempted: one bad entry must not
/// fail the whole run.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the host of an http(s) URL. Returns an error for anything that is
/// not a plain, unambiguous http(s) URL. Parsing is conservative: anything that
/// another URL parser might read differently (userinfo, backslashes, IPv6
/// literals, whitespace or control characters) is refused rather than guessed at.
fn host_of(url: &str) -> Result<String, String> {
    if url.chars().any(|c| c.is_whitespace() || c.is_control()) {
        return Err("url contains whitespace or control characters".into());
    }
    let lower = url.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return Err("unsupported url scheme (only http and https)".into());
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.contains('@') || authority.contains('\\') || authority.contains('[') {
        return Err("unsupported url authority".into());
    }

    let host = match authority.rfind(':') {
        Some(i) => {
            let port = &authority[i + 1..];
            if port.is_empty() || !port.bytes().all(|b| b.is_ascii_digit()) {
                return Err("invalid port".into());
            }
            &authority[..i]
        }
        None => authority,
    };
    let host = host.strip_suffix('.').unwrap_or(host);

    if host.is_empty() {
        return Err("missing host".into());
    }
    Ok(host.to_string())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();
        let mut seen: Vec<String> = Vec::new();

        for url in subscriptions.urls {
            let url = url.trim().to_string();
            if url.is_empty() {
                continue;
            }
            if seen.iter().any(|s| s == &url) {
                continue;
            }
            seen.push(url.clone());

            let host = match host_of(&url) {
                Ok(h) => h,
                Err(e) => {
                    failures.push(FetchFailure { url, error: e });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.iter().any(|allowed| *allowed == host) {
                failures.push(FetchFailure {
                    url,
                    error: "host not permitted for this node".into(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
